$ErrorActionPreference = "Stop"
$ProjectRoot = (Get-Location).Path
$ManifestPath = Join-Path $ProjectRoot "app/client-interface/manifest.ts"
if (-not (Test-Path -LiteralPath $ManifestPath)) {
  throw "Run this script from the VETRA project root (the folder containing app/client-interface/manifest.ts). Current folder: $ProjectRoot"
}
$ManifestBackup = "$ManifestPath.bak-$(Get-Date -Format yyyyMMdd-HHmmss)"
Copy-Item -LiteralPath $ManifestPath -Destination $ManifestBackup -Force
$IconDirectory = Join-Path $ProjectRoot "public/vetra-icons"
New-Item -ItemType Directory -Path $IconDirectory -Force | Out-Null

